// --- Vietnamese Section Types ---

import type { OptionalNullables } from './db.js';

export interface Deck {
    id: string;
    name: string;
    description: string | null;
    created_at: string;
    updated_at: string;
}

export type NewDeck = OptionalNullables<Omit<Deck, 'id' | 'created_at' | 'updated_at'>>;

export interface DeckStat {
    id: string;
    name: string;
    description: string | null;
    total_cards: number;
    due_cards: number;
    new_cards: number;
}

export interface Card {
    id: string;
    deck_id: string;
    front: string;
    back: string;
    audio: string | null;
    notes: string | null;
    created_at: string;
    updated_at: string;
}

export type NewCard = OptionalNullables<Omit<Card, 'id' | 'created_at' | 'updated_at'>>;

export const REVIEW_STATES = ['new', 'learning', 'review', 'relearning'] as const;
export type ReviewState = typeof REVIEW_STATES[number];

export const RATINGS = [1, 2, 3, 4] as const;
export type Rating = typeof RATINGS[number];

export interface Review {
    id: string;
    card_id: string;
    state: ReviewState;
    stability: number;
    difficulty: number;
    scheduled_days: number;
    elapsed_days: number;
    rating: Rating | null;
    due: string;
    last_review: string | null;
    created_at: string;
}

export type NewReview = OptionalNullables<Omit<Review, 'id' | 'created_at'>>;

/** Story 442: the five southern tones; ngã merges into hỏi in the south. */
export const SOUTHERN_TONES = ['ngang', 'huyền', 'sắc', 'hỏi', 'nặng'] as const;
export type SouthernTone = typeof SOUTHERN_TONES[number];

export interface ToneClip {
    id: string;
    word: string;
    tone: SouthernTone;
    audio: string;
    source: string;
    created_at: string;
    updated_at: string;
}
